import{i as e,o as t,r as n,t as r}from"./app-CKIWtCsy.js";var i=JSON.parse(`{"path":"/%E6%B0%B4%E7%8E%89%E6%87%90%E3%82%B2%E3%83%BC%E5%A4%9C%E8%A9%B1.html","title":"水玉懐ゲー夜話","lang":"en-US","frontmatter":{},"git":{},"readingTime":{"minutes":1.33,"words":400},"filePathRelative":"水玉懐ゲー夜話.md"}`),a={name:`水玉懐ゲー夜話.md`};function o(r,i,a,o,s,c){return t(),n(`div`,null,[...i[0]||=[e(`<h1 id="水玉懐ゲー夜話" tabindex="-1"><a class="header-anchor" href="#水玉懐ゲー夜話"><span>水玉懐ゲー夜話</span></a></h1><p><a href="./元祖水玉本舗.html">元祖水玉本舗</a>, <a href="./お絵描き.html">お絵描き</a>, <a href="./ライブ.html">ライブ</a></p><p>元祖水玉本舗を眺めつつ思い入れのあるゲームなどの回を模写とかしつつ語るお絵描きライブ。<a href="./それっぽく描くコツ2周目.html">それっぽく描くコツ2周目</a>の続き的なお絵描きライブ。</p><p><a href="https://www.youtube.com/playlist?list=PLLe3xJa7mDEk" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話(プレイリスト） - YouTube</a></p><p>tinyurl: https://tinyurl.com/5e9rakrs</p><h2 id="配信テンプレ" tabindex="-1"><a class="header-anchor" href="#配信テンプレ"><span>配信テンプレ</span></a></h2><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">今回はワルキューレの伝説です #水玉懐ゲー夜話</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">水玉懐ゲー夜話：ワルキューレの伝説</span>
<span class="line"></span>
<span class="line">元祖水玉本舗から思い入れのあるゲームの回を選んで模写しつつ、水玉本舗やゲームについて語るライブ配信です。</span>
<span class="line"></span>
<span class="line">web: https://tinyurl.com/5e9rakrs</span>
<span class="line">水玉懐ゲー夜話プレイリスト https://www.youtube.com/playlist?list=PLLe3xJa7mDEk</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="ワルキューレの伝説" tabindex="-1"><a class="header-anchor" href="#ワルキューレの伝説"><span>ワルキューレの伝説</span></a></h2><p><a href="https://www.youtube.com/live/kLj20YT7p-w" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話：ワルキューレの伝説 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0815_221935-DthOSlo3.png" alt="imgs/MizuTama/2026_0815_221935.png"><img src="/RandomThoughts/assets/2026_0815_221939-Bk55un7v.png" alt="imgs/MizuTama/2026_0815_221939.png"></p><p>ドット絵が動く事で完成するという水玉先生の言う事がめちゃ分かる。ジャンプしているのがいいんだよな、ワルキューレ。音楽も好きだし。</p><h2 id="ワンダープロジェクトj" tabindex="-1"><a class="header-anchor" href="#ワンダープロジェクトj"><span>ワンダープロジェクトJ</span></a></h2><p><a href="https://www.youtube.com/live/iFabpsYUVzM" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話：ワンダープロジェクトJ - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0802_220507-BHEx1EXj.png" alt="imgs/MizuTama/2026_0802_220507.png"></p><p>本番は見てるだけで手が出せない、というのがハラハラドキドキでいいゲームだったよなぁ。</p><p>ちょっとこの絵は未完成で時間切れだったので、気が済むまで描いてみた。</p><p><img src="/RandomThoughts/assets/2026_0802_232413-skXq7xIZ.png" alt="imgs/MizuTama/2026_0802_232413.png"></p><p>時間切れっぽい奴は、終わった後に完成までやった版も作ってもいいかな、という気はしている。 あんまり細部の修正を何度もやって全然終わらない、みたいなのは避けたいとも思っているが。</p><h2 id="ゼルダの伝説夢を見る島" tabindex="-1"><a class="header-anchor" href="#ゼルダの伝説夢を見る島"><span>ゼルダの伝説夢を見る島</span></a></h2><p><a href="https://www.youtube.com/live/HstMn_COBR0" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話：ゼルダの伝説夢を見る島 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0801_214125-Cf9xQr-F.png" alt="imgs/MizuTama/2026_0801_214125.png"></p><p>かぢばあたる先生の漫画の思い出が強いけど、ゲームも結構思い出深いなぁ、と配信していて思った。ゲームボーイ、我々の世代にはなんか象徴的なハードウェアだよなぁ。 夢を見る島は最高傑作なんじゃないか。</p><h2 id="ファイアーエムブレム、紋章の謎" tabindex="-1"><a class="header-anchor" href="#ファイアーエムブレム、紋章の謎"><span>ファイアーエムブレム、紋章の謎</span></a></h2><p><a href="https://www.youtube.com/live/YolKGhO3UEo" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話：ファイアーエムブレム紋章の謎 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0729_220321-DsFJwdgN.png" alt="imgs/MizuTama/2026_0729_220321.png"></p><p>ちょっと最初にどこを描くか決めかねて間に合わんかった。まぁこういう事もあるよなぁ。 後で気が向いたら完成させるかもしれません。</p><p><img src="/RandomThoughts/assets/2026_0729_230742-D4dDUm5H.png" alt="imgs/MizuTama/2026_0729_230742.png"></p><p>という事でもう少し気が済むまで手を入れた。</p><p>水玉先生のファイアーエムブレム回は凄くいいですよねぇ。 三姉妹も可愛いし、シーダとマルスも良いし。</p><p>ナバールとかの細い系のキャラの色気みたいなのに水玉先生の好みが良くでているなぁ、と思う。</p><h2 id="聖剣伝説2" tabindex="-1"><a class="header-anchor" href="#聖剣伝説2"><span>聖剣伝説2</span></a></h2><p><a href="https://www.youtube.com/live/6Pw_mwgPVQs" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話：聖剣伝説2 - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0727_215221-DAcPFk6S.png" alt="imgs/MizuTama/2026_0727_215221.png"></p><p>聖剣伝説2の回の元祖水玉本舗はいいよなぁ。 絵はもうちょっと練習したい感じもするが、喋ってこのくらいの絵を描く、というのをやっていきたい。</p><h2 id="ぷよぷよ-無印" tabindex="-1"><a class="header-anchor" href="#ぷよぷよ-無印"><span>ぷよぷよ（無印）</span></a></h2><p><a href="https://www.youtube.com/live/ECYeO5hQQ1I" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話：ぷよぷよ（無印） - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0726_214512-D9AC4JMd.png" alt="imgs/MizuTama/2026_0726_214512.png"></p><p><img src="/RandomThoughts/assets/2026_0726_214524-CnJtG_SB.png" alt="imgs/MizuTama/2026_0726_214524.png"></p><p>無印は今となっては対戦としては成立してないですが、そこに至るまでのそれぞれの思い出はありますやね。 キャラ的な思い出もぷよ1は多いし、ゲーム自体というよりもやっていた時の空間を思い出す。</p><h2 id="ランドストーカー" tabindex="-1"><a class="header-anchor" href="#ランドストーカー"><span>ランドストーカー</span></a></h2><p><a href="https://www.youtube.com/live/LwIlGwXFulw" target="_blank" rel="noopener noreferrer">水玉懐ゲー夜話：ランドストーカー - YouTube</a></p><p><img src="/RandomThoughts/assets/2026_0725_213801-CPyeUvXF.png" alt="imgs/MizuTama/2026_0725_213801.png"></p><p>ちょっとライルを描く時間は無いなぁ。 練習していけばライルだけ描くくらいは出来るようになるかもしれないが。</p><p>本当はもっといろんなキャラを描いていきながら雑談したいのだが、まだサブキャラを一つで精一杯だな。</p><p>一方で結構楽しくやっていけそうな気はしているので、しばらく続けていきたい。</p>`,46)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};